import{_ as o,c as e,o as r,ah as s}from"./chunks/framework.RCw5T9E9.js";const h=JSON.parse('{"title":"Options → AI","description":"","frontmatter":{"title":"Options → AI"},"headers":[],"relativePath":"ru/ai/settings.md","filePath":"ru/ai/settings.md"}'),n={name:"ru/ai/settings.md"};function d(a,t,g,i,l,c){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="options-→-ai" tabindex="-1">Options → AI <a class="header-anchor" href="#options-→-ai" aria-label="Permalink to &quot;Options → AI&quot;">​</a></h1><p><strong>Options → AI</strong> — это раздел с подписью <strong>AI</strong>. Шестерёнка на вкладке <a href="/qa-tools/docs/ru/ai/general.html">AI-ассистент</a> открывает <strong>Connection</strong>. <strong>Review access</strong> на той вкладке открывает <strong>Agent access</strong>.</p><p>Блоки идут в таком порядке: <strong>Connection</strong>, <strong>Models</strong>, <strong>Personalization</strong>, <strong>Agent access</strong>, <strong>Data masking for AI</strong>.</p><p>Эти настройки хранятся в этом браузере отдельно от профиля инспектора. <strong>Export</strong> и <strong>Import</strong> в <a href="/qa-tools/docs/ru/options/settings_management.html">Менеджере настроек</a> включают их: в JSON это объект <code>ai</code>. Ключи API и <strong>Extra headers</strong> своих провайдеров в файл не записываются и при импорте не применяются. Свои провайдеры записываются без них; при импорте провайдер с тем же id сохраняет ключ, заголовки и подтверждение из этого браузера, новый приходит без ключа и снова спрашивает подтверждение, а провайдеры, которые есть только в этом браузере, остаются. <strong>Reset</strong> не очищает <strong>Options → AI</strong>, включая ключи и счётчики запросов за сегодня. На экране написано: <em>Keys stay in this browser and are not included in settings export.</em></p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><p>Сначала <strong>OpenRouter</strong>, затем <strong>Gemini</strong>. У каждой строки подпись <strong>your own API key</strong>.</p><p>Сохранённый ключ показан как восемь точек и последние четыре символа, рядом <strong>Remove</strong>. <strong>Remove</strong> стирает этот ключ и не меняет провайдера, выбранного на вкладке AI.</p><p>Пустой ключ — поле пароля <strong>OpenRouter API key</strong> или <strong>Gemini API key</strong> и кнопка <strong>Save</strong>. <strong>Save</strong> недоступна, пока поле пустое или в нём одни пробелы. Сохраняется текст без пробелов по краям. Сохранение также выбирает этого провайдера на вкладке AI.</p><p>Под OpenRouter: <strong>Get a free key in</strong> <a href="https://openrouter.ai/settings/keys" target="_blank" rel="noreferrer">OpenRouter</a>. Под Gemini: <strong>Get a free key in</strong> <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">Google AI Studio</a>.</p><p>Пока ни один ключ не сохранён, вкладка AI использует <strong>Gemini</strong>.</p><h3 id="your-own-providers" tabindex="-1">Свои провайдеры <a class="header-anchor" href="#your-own-providers" aria-label="Permalink to &quot;Свои провайдеры {#your-own-providers}&quot;">​</a></h3><p>Под встроенными провайдерами — <strong>Your own providers</strong> с подписью <em>OpenAI, DeepSeek, local models, OpenAI-compatible agents</em>. Подходит любой сервер, который отвечает на <code>POST {Base URL}/chat/completions</code> в формате OpenAI: облачный ключ API, модель на вашей машине или собственный агент. Каждый провайдер — строка с именем, а под ним хост, <strong>local</strong> для адреса на этой машине или в локальной сети, ключ в виде восьми точек и последних четырёх символов (или <strong>no key</strong>) и режим инструментов. <strong>Edit the connection</strong> открывает тот же диалог, что и <strong>Add provider</strong>. <strong>Remove the connection</strong> переспрашивает в самой строке (<strong>Remove</strong> / <strong>Keep</strong>); удаление стирает ключ, выбор моделей и отметки моделей этого провайдера, а вкладка AI переключается на встроенного провайдера.</p><p><strong>Add provider</strong> открывает <strong>Add your own provider</strong>:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Пресет, который заполняет поля ниже; см. следующую таблицу. Смена пресета меняет только поля, которые ещё совпадают со значениями прежнего пресета</td></tr><tr><td><strong>Name</strong></td><td>До 40 символов, видно в меню провайдеров</td></tr><tr><td><strong>Base URL</strong></td><td>До версии API включительно, например <code>https://api.openai.com/v1</code>. Завершающий <code>/</code> или <code>/chat/completions</code> убирается. Под полем — куда пойдут запросы или предупреждение для удалённого адреса <code>http://</code> (ключ и данные идут без шифрования)</td></tr><tr><td><strong>API key</strong></td><td>Обязателен для OpenAI и DeepSeek, для остальных типов — по желанию. Отправляется как <code>Authorization: Bearer …</code></td></tr><tr><td><strong>Tools</strong> (Advanced)</td><td><strong>Native tool calls</strong> — поле <code>tools</code> в API. <strong>Tools as text</strong> — для серверов, которые не принимают <code>tools</code>: инструменты описываются в системном промпте, модель пишет <code>&lt;tool_call&gt;{…}&lt;/tool_call&gt;</code>, результаты возвращаются сообщениями пользователя. <strong>No tools</strong> — модель отвечает только по вопросу, вложениям и выжимке логов</td></tr><tr><td><strong>Context size</strong> (Advanced)</td><td><strong>Small (8K tokens)</strong>, <strong>Medium (32K)</strong> или <strong>Large (128K+)</strong>. Чем меньше, тем короче выжимка логов, сильнее обрезаются результаты инструментов, раньше отбрасываются прошлые вопросы и меньше раундов инструментов (6, 8 и 10)</td></tr><tr><td><strong>Stream answers</strong> (Advanced)</td><td>Включено по умолчанию. Выключите, если сервер ломает потоковые ответы</td></tr><tr><td><strong>Extra headers</strong> (Advanced)</td><td>По одному в строке, <code>Name: value</code>, для шлюзов и прокси (например <code>api-key: …</code>). Заголовок с именем <code>Authorization</code> заменяет стандартный</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Тип</th><th>Base URL</th><th>Ключ</th><th>Контекст</th><th>Примечания</th></tr></thead><tbody><tr><td><strong>OpenAI</strong></td><td><code>https://api.openai.com/v1</code></td><td>обязателен</td><td>Large</td><td>Оплачивается с вашего аккаунта OpenAI. Рассуждающим моделям (<code>o…</code>, <code>gpt-5…</code>) <code>temperature</code> не передаётся</td></tr><tr><td><strong>DeepSeek</strong></td><td><code>https://api.deepseek.com/v1</code></td><td>обязателен</td><td>Large</td><td>Оплачивается с баланса DeepSeek. Рассуждения <code>deepseek-reasoner</code> показываются как размышления</td></tr><tr><td><strong>Ollama</strong></td><td><code>http://localhost:11434/v1</code></td><td>—</td><td>Small</td><td>Запускайте Ollama с <code>OLLAMA_ORIGINS=chrome-extension://*</code> (или <code>*</code>), иначе она отвечает расширению 403. Для длинных чатов увеличьте <code>OLLAMA_CONTEXT_LENGTH</code> (например 16384). Выбирайте модель с поддержкой инструментов</td></tr><tr><td><strong>LM Studio</strong></td><td><code>http://localhost:1234/v1</code></td><td>—</td><td>Medium</td><td>Запустите сервер в <strong>Developer</strong> и включите <strong>CORS</strong></td></tr><tr><td><strong>OpenAI-compatible</strong></td><td>свой</td><td>по желанию</td><td>Medium</td><td>vLLM, llama.cpp, LiteLLM, Groq, Mistral, xAI, Together, собственный агент</td></tr></tbody></table><p><strong>Test connection</strong> запрашивает список моделей (<code>GET {Base URL}/models</code>) и отправляет один короткий запрос с тестовым инструментом. По результату выбирается <strong>Tools</strong>: <strong>Native tool calls</strong>, если модель вызвала инструмент, и <strong>Tools as text</strong>, если она его проигнорировала или сервер отклонил поле <code>tools</code>. <strong>Model id for the test</strong> указывать не обязательно; без него берётся первая предложенная модель. Для сервера без списка моделей id нужен; при <strong>Add</strong>/<strong>Save</strong> он добавляется в модели провайдера. Ошибка показывает сообщение и <strong>Server response</strong>.</p><p>Первый вопрос новому провайдеру снова просит подтверждение: <strong>Data sent to {имя} ({хост})</strong>. В тексте сказано, локальный ли сервер или что данные уходят на этот хост по его условиям.</p><p>Частые ошибки своих провайдеров:</p><ul><li><strong>Could not reach {имя} ({хост})</strong> — сервер не запущен, адрес неверный или (на <a href="/qa-tools/docs/ru/standalone.html">standalone</a>-странице) сервер не разрешает запросы с другого origin.</li><li><strong>{имя} refused the request from the extension</strong> — локальный сервер отклонил origin расширения (Ollama: <code>OLLAMA_ORIGINS</code>).</li><li><strong>{имя}: {хост} has no such endpoint</strong> — проверьте <strong>Base URL</strong>; обычно он заканчивается на <code>/v1</code>.</li><li><strong>{имя} rejected tool calls</strong> — переключите <strong>Tools</strong> на <strong>Tools as text</strong> или <strong>No tools</strong>.</li><li><strong>{имя}: the account has no credits or quota left.</strong></li></ul><p>Если сервер отвечает HTTP 400 на <code>temperature</code>, <code>stream_options</code> или <code>tool_choice</code>, запрос один раз повторяется без этого параметра, и до перезагрузки страницы расширения этот параметр серверу больше не отправляется.</p><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><p>Меню провайдера здесь только выбирает, чей список редактировать. Сначала это провайдер, выбранный на вкладке AI. Смена здесь его не переключает.</p><p><strong>Reload the model list</strong> недоступна, пока список загружается. Когда список загружен, справа <strong>N of M available</strong>: <strong>M</strong> — рекомендованные модели плюс добавленные, <strong>N</strong> — сколько из них всё ещё отмечено.</p><p>В меню провайдера — OpenRouter, Gemini и свои провайдеры. Поле <strong>Add or search model</strong> недоступно, пока у этого провайдера нет ключа (свой провайдер считается подключённым сразу после добавления). Без ключа строка <strong>Connect OpenRouter above to see its models.</strong> или <strong>Connect Gemini above to see its models.</strong> Пока список грузится: <strong>Loading models...</strong> Ошибка показывает текст ошибки; у своих провайдеров уже добавленные модели остаются в списке под ней.</p><p>Список открывается при фокусе. <strong>Escape</strong> или клик снаружи его закрывает.</p><ul><li>Пустое поле показывает бесплатные модели. Подсказка: <strong>Free models. Type to search paid ones too.</strong></li><li>Любой текст ищет по имени или id без учёта регистра, среди бесплатных и платных. Подсказка: <strong>All models of the provider, free and paid.</strong> Сначала бесплатные, затем по имени.</li><li>Показано не больше <strong>60</strong> строк. Остаток: <strong>N more, refine the search</strong>.</li><li>Ничего не найдено: <strong>No models found</strong>.</li></ul><p>У строки имя, id и метка <strong>free</strong> или <strong>paid</strong>. Модели <strong>recommended</strong> уже в списке, их флажок недоступен. Отметка другой модели её добавляет. На вкладке AI добавленные модели идут в группе <strong>Added</strong>.</p><p>У своих провайдеров список берётся из <code>GET {Base URL}/models</code> без моделей эмбеддингов, речи и изображений, меток <strong>free</strong>/<strong>paid</strong> нет, подсказка — <strong>Models the server lists</strong>. У локальных провайдеров и у списков до 8 моделей рекомендованы все модели; в длинных списках рекомендуется до трёх (OpenAI: <code>gpt-5-mini</code>, <code>gpt-5</code>, <code>gpt-4.1-mini</code>…; DeepSeek: <code>deepseek-chat</code>, <code>deepseek-reasoner</code>). В поле написано <strong>Add or search model, or type a model id</strong>: введённый id, которого нет в списке сервера, показывает <strong>Add model id …</strong>, <strong>Enter</strong> тоже его добавляет. Так добавляются модели агентов и шлюзов без списка моделей. <strong>Auto</strong> у своих провайдеров выбирает из моделей списка и переключается при ошибках.</p><p>Под полем — эти рекомендованные и добавленные модели.</p><ul><li>Отмеченная строка доступна. Снятие отметки прячет её с вкладки AI и из <strong>Auto</strong>. Имя зачёркнуто. Под именем может быть <strong>quota used up, resets in …</strong>, <strong>not available for this key</strong> или <strong>busy, retry in …</strong>. В подсказке — сообщение провайдера. <strong>N today</strong> — сколько запросов к этой модели было сегодня. Метки: <strong>recommended</strong>, <strong>unstable</strong>, <strong>paid</strong>.</li><li>Последнюю отмеченную модель снять нельзя.</li><li><strong>Remove from the list</strong> есть у моделей без метки recommended. Кнопка недоступна у последней отмеченной. Рекомендованные из списка не удаляются; их скрывают снятием отметки.</li></ul><h2 id="personalization" tabindex="-1">Personalization <a class="header-anchor" href="#personalization" aria-label="Permalink to &quot;Personalization&quot;">​</a></h2><p><strong>Defaults</strong> недоступна, пока блок уже в значениях по умолчанию: тон <strong>Default</strong>, объём <strong>Normal</strong>, маршрутизация <strong>Lite</strong> и пустое поле стиля.</p><p><strong>Base style and tone</strong></p><table tabindex="0"><thead><tr><th>Значение</th><th>Подсказка</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>Balanced answers</td></tr><tr><td><strong>Professional</strong></td><td>Precise, neutral wording</td></tr><tr><td><strong>Friendly</strong></td><td>Supportive, plain words</td></tr><tr><td><strong>Direct</strong></td><td>Conclusion first, no filler</td></tr><tr><td><strong>Mentor</strong></td><td>Explains the concepts behind the cause</td></tr></tbody></table><p><strong>Answer detail</strong></p><table tabindex="0"><thead><tr><th>Значение</th><th>Подсказка</th></tr></thead><tbody><tr><td><strong>Brief</strong></td><td>Cause, key evidence and the fix in a few lines</td></tr><tr><td><strong>Normal</strong></td><td>What went wrong, the cause, the evidence and the fix</td></tr><tr><td><strong>Detailed</strong></td><td>The whole chain of events, ruled-out causes, steps to reproduce</td></tr></tbody></table><p><strong>Instruction routing</strong></p><table tabindex="0"><thead><tr><th>Значение</th><th>Подсказка</th></tr></thead><tbody><tr><td><strong>Full</strong></td><td>All task instructions in every request. For strong models</td></tr><tr><td><strong>Lite</strong></td><td>Core rules only; the model loads the instructions of the task when needed</td></tr></tbody></table><p><strong>Your style instructions</strong> вмещает до <strong>2000</strong> символов. Подсказка поля: <strong>For example: answer in Russian, end with a short checklist for the bug report</strong>. Счётчик: <strong>N / 2000</strong>. Текст сохраняется примерно через <strong>400 мс</strong> после последнего изменения. <strong>Defaults</strong> в это окно может перезаписать отложенное сохранение, и стёртый текст вернётся.</p><h2 id="agent-access" tabindex="-1">Agent access <a class="header-anchor" href="#agent-access" aria-label="Permalink to &quot;Agent access&quot;">​</a></h2><p>Описание: <strong>What the assistant may read and send to the provider.</strong> <strong>Defaults</strong> возвращает значения ниже и недоступна, пока они уже стоят.</p><p><strong>Attach the logs digest to questions</strong> — подсказка <strong>A short summary of errors and the timeline.</strong> По умолчанию <strong>Allowed</strong>. <strong>Off</strong> отправляет вопрос без этой сводки. Первый шаг ответа тогда пишет <strong>no logs digest (turned off)</strong>.</p><p><strong>Tools.</strong> У каждой группы <strong>Allowed</strong>, <strong>Ask each time</strong> или <strong>Off</strong>. По умолчанию <strong>Ask each time</strong>. <strong>Ask each time</strong> — это подтверждение на вкладке <a href="/qa-tools/docs/ru/ai/general.html">AI-ассистент</a>. <strong>Allowed</strong> выполняет инструмент без вопроса. <strong>Off</strong> не отдаёт эту группу ассистенту. Чтение этой документации остаётся доступным.</p><table tabindex="0"><thead><tr><th>Группа</th><th>Подсказка</th></tr></thead><tbody><tr><td><strong>Logs</strong></td><td>Event details and search over the captured logs</td></tr><tr><td><strong>Page code</strong></td><td>List, read and search the scripts of the page and their source maps</td></tr><tr><td><strong>Live page</strong></td><td>Find elements on the page, why they are disabled or hidden, their components, handler code and the current store state</td></tr></tbody></table><p><strong>Data in the logs.</strong> У каждой строки <strong>Allowed</strong> или <strong>Off</strong>. Все три по умолчанию <strong>Allowed</strong>. <strong>Off</strong> подставляет вместо скрытой части <code>[hidden by AI access settings]</code>. Выключенные значения стора, props, emit и action становятся типом в скобках, например <code>[string]</code>; имена и пути остаются.</p><table tabindex="0"><thead><tr><th>Строка</th><th>Подсказка</th></tr></thead><tbody><tr><td><strong>Request and response headers</strong></td><td>Sensitive headers stay masked</td></tr><tr><td><strong>Request / response bodies and WebSocket messages</strong></td><td></td></tr><tr><td><strong>Values of store state, props, emits and actions</strong></td><td>Off: only names, paths and types</td></tr></tbody></table><h2 id="data-masking-for-ai" tabindex="-1">Data masking for AI <a class="header-anchor" href="#data-masking-for-ai" aria-label="Permalink to &quot;Data masking for AI&quot;">​</a></h2><p>Этот список применяется, когда данные уходят провайдеру. Вкладку <strong>Logs</strong> и HTML-отчёт он не меняет. Маска логов по-прежнему срабатывает первой. Как фрагмент совпадает с ключом и что значат <code>[MASKED]</code>, <code>[MASKED JWT]</code>, <code>Bearer [MASKED]</code> и <code>[MASKED CARD]</code>, описано в <a href="/qa-tools/docs/ru/logs/settings.html#data-masking">Data masking</a>.</p><p>Текст под заголовком: <strong>Values with matching names in objects, headers, URLs, and code are sent as [MASKED].</strong></p><p><strong>Mask sensitive data</strong> — это флажок шаблонов значений. Он включён по умолчанию. Пока он выключен, действует только список ключей.</p><p>Колонка — <strong>Key contains</strong>. Пустая таблица: <strong>No keys — only value patterns are masked</strong>. Подсказка поля: <strong>Key fragment, e.g. x-client-secret</strong>. <strong>Add</strong> или <strong>Enter</strong> обрезает фрагмент. Пустое значение: <strong>Key cannot be empty</strong>. Тот же фрагмент без учёта регистра: <strong>This key is already in the list</strong>. Меню строки — <strong>Delete</strong>. Клик по строке ничего не делает.</p><p>Фрагменты по умолчанию — это <a href="/qa-tools/docs/ru/logs/settings.html#data-masking">список логов</a> плюс <code>passcode</code>, <code>auth</code>, <code>bearer</code>, <code>jwt</code>, <code>credential</code>, <code>session</code>, <code>csrf</code>, <code>xsrf</code>, <code>signature</code>, <code>accesskey</code>, <code>passphrase</code>.</p><p><code>passcode</code> возвращается в список, если сохранённый список его ещё не содержит. <strong>Delete</strong> у этой строки не оставляет её удалённой.</p><p><strong>Defaults</strong> восстанавливает список ключей и включает <strong>Mask sensitive data</strong>. Кнопка остаётся доступной, даже если список уже такой.</p>',54)])])}const m=o(n,[["render",d]]);export{h as __pageData,m as default};
